49:     /// 白名单判定。白名单之外一次失败即终局——不猜、不重试。
50:     pub fn is_retryable(kind: ModelErrorKind) -> bool {
51:         matches!(
52:             kind,
53:             ModelErrorKind::RateLimited
54:                 | ModelErrorKind::Timeout
55:                 | ModelErrorKind::Network
56:                 | ModelErrorKind::Server
57:                 | ModelErrorKind::EmptyResponse
58:         )
59:     }
60: 
61:     /// 第 `retry` 次重试（从 1 起）该等多久；`None` = 放弃重试。
62:     ///
63:     /// - 端点给了 `Retry-After` 就优先采用；超过 `max_delay` 直接放弃，不自行缩短；
64:     /// - 否则指数退避 `initial * 2^(retry-1)`，封顶 `max_delay`，再乘对称抖动并二次封顶。
65:     ///
66:     /// `random01` 由调用方注入（`[0, 1]`），生产用 [`random01`]，测试用固定值。
67:     pub fn delay(&self, retry: u32, _provider_retry_after_ms: Option<u64>, random01: f64) -> Option<Duration> {
68:         if retry == 0 || retry > self.max_retries {
69:             return None;
70:         }
71:         // `2^(retry-1)` 用移位算，先夹住指数防止手写超大次数时溢出。
72:         let exponent = retry.saturating_sub(1).min(20);
73:         let exponential = self.initial_delay.saturating_mul(1u32 << exponent).min(self.max_delay);
74:         let jitter = 1.0 - self.jitter_ratio + 2.0 * self.jitter_ratio * random01.clamp(0.0, 1.0);
75:         Some(exponential.mul_f64(jitter).min(self.max_delay))
76:     }
77: }
