79: /// 生产用随机源：`[0, 1)`。系统熵源不可用时退回时钟低位，不 panic——
80: /// 抖动只影响等待的分布，不影响正确性。
81: pub fn random01() -> f64 {
82:     let mut bytes = [0u8; 8];
83:     if getrandom::fill(&mut bytes).is_ok() {
84:         // 取高 53 位映射到 [0, 1)，与 f64 尾数精度一致。
85:         return (u64::from_le_bytes(bytes) >> 11) as f64 / (1u64 << 53) as f64;
86:     }
87:     let nanos = SystemTime::now().duration_since(UNIX_EPOCH).map(|d| d.subsec_nanos()).unwrap_or(0);
88:     f64::from(nanos) / 1e9
89: }
